import{_ as t,a,o as r,a6 as s}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Returns (RMA)","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/sales/returns/index.md","filePath":"api/rest-api/admin/sales/returns/index.md","lastUpdated":1787725411000}'),o={name:"api/rest-api/admin/sales/returns/index.md"};function n(d,e,i,c,u,h){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="returns-rma" tabindex="-1">Returns (RMA) <a class="header-anchor" href="#returns-rma" aria-label="Permalink to &quot;Returns (RMA)&quot;">​</a></h1><p>The Returns menu is the admin queue for <strong>RMA (Return Merchandise Authorization) requests</strong> — the returns and item-cancellations customers raise against their orders. It mirrors the admin <strong>Sales → Returns</strong> screen: browse the queue, open a request for detail, create a return for any order, move a request through its status workflow, reopen a closed one, and exchange messages with the customer.</p><h2 id="what-a-return-holds" tabindex="-1">What a return holds <a class="header-anchor" href="#what-a-return-holds" aria-label="Permalink to &quot;What a return holds&quot;">​</a></h2><p>Each RMA request records the order it belongs to (<code>orderId</code> / <code>orderIncrementId</code> / <code>orderStatus</code>), the customer context (<code>customerName</code> / <code>customerEmail</code> / <code>isGuest</code>), the current status (<code>statusId</code> / <code>statusTitle</code> / <code>statusColor</code>), the package condition, an optional <code>information</code> note, and the single returned <code>item</code> (with its resolution and reason). Attached proof images are listed in <code>images</code>.</p><p>The nested <code>item</code> object uses snake_case keys: <code>id</code>, <code>order_item_id</code>, <code>sku</code>, <code>name</code>, <code>quantity</code>, <code>resolution</code> (<code>return</code> or <code>cancel_items</code>), <code>reason_id</code>, <code>reason</code>, <code>variant_id</code>.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A request moves through a set of statuses (Pending, Accept, Declined, Dispatched package, Received package, Item canceled, …). Each request&#39;s <code>availableStatuses</code> field lists the exact status transitions the admin may set next — a list of <code>{ id, title }</code>. Use those ids when calling <strong>Update Status</strong>.</p><h2 id="update-status-—-the-action-semantics" tabindex="-1">Update Status — the action semantics <a class="header-anchor" href="#update-status-—-the-action-semantics" aria-label="Permalink to &quot;Update Status — the action semantics&quot;">​</a></h2><p>Setting a status is more than a label change for two special statuses:</p><ul><li><strong>Received package</strong> (status id <code>5</code>) — creates a <strong>refund</strong> for the returned item. Send a <code>shipping</code> amount to include shipping in the refund; omit or send <code>0</code> to refund the item only.</li><li><strong>Item canceled</strong> (status id <code>8</code>) — <strong>cancels the order item</strong> and restores its inventory.</li></ul><p>Any other status just updates the status. Every status change adds a note to the conversation and notifies the customer.</p><h2 id="reopen" tabindex="-1">Reopen <a class="header-anchor" href="#reopen" aria-label="Permalink to &quot;Reopen&quot;">​</a></h2><p>A declined or canceled request can be <strong>reopened</strong> back to Pending when store settings allow it (otherwise the request returns <code>422</code>). The <code>canReopen</code> flag on the detail tells you whether reopening is currently possible.</p><h2 id="creating-a-return" tabindex="-1">Creating a return <a class="header-anchor" href="#creating-a-return" aria-label="Permalink to &quot;Creating a return&quot;">​</a></h2><p>To open a return for an order, first list the order&#39;s <strong>returnable items</strong> to get the trusted quantity caps, and the active <strong>return reasons</strong> for the chosen resolution type, then POST the return. <code>rma_qty</code> is capped server-side by the item&#39;s returnable/cancelable quantity. Optional proof images can be attached via multipart <code>images[]</code>.</p><h2 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages&quot;">​</a></h2><p>Each request has a conversation thread. <strong>List Messages</strong> returns the thread newest-first; <strong>Send Message</strong> posts an admin reply and notifies the customer.</p><h2 id="response-shape" tabindex="-1">Response shape <a class="header-anchor" href="#response-shape" aria-label="Permalink to &quot;Response shape&quot;">​</a></h2><p>The returns <strong>listing</strong> is wrapped in a <code>{ data: [...], meta: {...} }</code> envelope (<code>meta</code> = <code>currentPage</code>, <code>perPage</code>, <code>lastPage</code>, <code>total</code>, <code>from</code>, <code>to</code>). Detail-only fields (<code>item</code>, <code>images</code>, <code>availableStatuses</code>, <code>information</code>, <code>packageCondition</code>, <code>canReopen</code>, <code>messagesCount</code>) are <code>null</code> on the listing rows.</p><p>The three read-only helper lists — <strong>returnable items</strong>, <strong>return reasons</strong>, and <strong>return messages</strong> — are returned as <strong>plain JSON arrays</strong> (no envelope).</p><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="./list-returns.html">List returns</a></td><td><code>GET /api/admin/rma/requests</code></td></tr><tr><td><a href="./get-return.html">Get a return</a></td><td><code>GET /api/admin/rma/requests/{id}</code></td></tr><tr><td><a href="./create-return.html">Create a return</a></td><td><code>POST /api/admin/rma/requests</code></td></tr><tr><td><a href="./update-status.html">Update status</a></td><td><code>POST /api/admin/rma/requests/{id}/update-status</code></td></tr><tr><td><a href="./reopen-return.html">Reopen a return</a></td><td><code>POST /api/admin/rma/requests/{id}/reopen</code></td></tr><tr><td><a href="./list-returnable-items.html">List returnable items</a></td><td><code>GET /api/admin/rma/requests/order-items?order_id=</code></td></tr><tr><td><a href="./list-return-reasons.html">List return reasons</a></td><td><code>GET /api/admin/rma/requests/resolution-reasons?resolution_type=</code></td></tr><tr><td><a href="./list-return-messages.html">List return messages</a></td><td><code>GET /api/admin/rma/messages?return_id=</code></td></tr><tr><td><a href="./send-return-message.html">Send a message</a></td><td><code>POST /api/admin/rma/messages</code></td></tr></tbody></table><p>Permissions: <code>sales.rma.requests</code> for reads / status changes / reopen / messages, and <code>sales.rma.requests.create</code> to create a return.</p>',23)]))}const p=t(o,[["render",n]]);export{m as __pageData,p as default};
